{
  "contract": "GoodMorning",
  "closure": {
    "site_function": "swapBack",
    "site_call": ".addLiquidityETH",
    "functions": [
      "transfer",
      "transferFrom",
      "approve",
      "clearERC20Token",
      "manualSend",
      "setSwapBackSettings",
      "setFees"
    ],
    "justification": "Includes all public/external functions that could affect inSwap and swapThreshold, directly or indirectly, during reentrancy."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom",
      "approve",
      "clearERC20Token",
      "manualSend",
      "setSwapBackSettings",
      "setFees"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1,
      "approve": 1,
      "clearERC20Token": 1,
      "manualSend": 1,
      "setSwapBackSettings": 1,
      "setFees": 1
    }
  },
  "phases": {
    "function": "swapBack",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before .addLiquidityETH"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before .addLiquidityETH",
      "to_marker": "after .addLiquidityETH"
    },
    "post": {
      "name": "post",
      "from_marker": "after .addLiquidityETH",
      "to_marker": "exit"
    },
    "linearization_point": "after .addLiquidityETH"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Tracks the amount of assets in-flight during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__rOwned == _totalProportion + inFlight",
    "stable_formula": "_sum__rOwned == _totalProportion",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__rOwned == _totalProportion",
    "rule": "The exposure invariant ensures conservation of _rOwned across the callback window, accounting for in-flight changes."
  }
}
